import { createFileRoute } from '@tanstack/react-router';
import { CurrentUser, SignIn } from '../features/session/SignIn';
import { useCurrentSheet, useCurrentUser } from '../features/session/useSession';
import { SheetPicker } from '../features/sheet/SheetPicker';
import { SheetPanels } from '../slots/defs/sheetPanels';

// The one screen. Sign in first; then load a sheet, whose content fills the sheet.panels slot.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();

  if (user === '') return <SignIn />;
  return (
    <>
      <CurrentUser user={user} />
      <SheetPicker />
      {sheet === '' ? (
        <p data-testid="home-empty">Nothing here yet.</p>
      ) : (
        // Keyed by sheet so loading another sheet starts its panels afresh.
        <SheetPanels.Slot key={sheet} user={user} sheet={sheet} />
      )}
    </>
  );
}
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { Fragment, createElement } from 'react';
import type { ComponentType, ReactElement } from 'react';
import { forSlot } from './registry';

// ── Slots: regions of the UI that features fill ───────────────────────────────────────────────
// A SLOT is a region of the UI that features fill. Whatever renders a region does not list what
// goes in it; a contribution to a region (a panel, a table column, a row action, a toolbar
// control, a nav link) is a separate file, registered by discovery (slots/discover.ts).
//
//   1. declare a region  ->  slots/defs/projectDetail.ts
//        export const ProjectDetail = defineSlot<{ projectId: number }>('project.detail');
//   2. render it         ->  <ProjectDetail.Slot projectId={id} />
//   3. fill it           ->  features/projects/notes.slot.tsx
//        export const contribution = ProjectDetail.fill({ order: 30, Component: ProjectNotes });
//
// This file, slots/registry.ts and slots/discover.ts implement that mechanism; a region is
// declared by a file under slots/defs/.

export type Contribution<Ctx> = {
  /** Lower renders first; equal orders fall back to file path, so the order is always stable. */
  order?: number;
  Component: ComponentType<Ctx>;
};

export type SlotDef<Ctx extends object> = {
  id: string;
  /** Renders the region. Its props ARE the context handed to every contribution. */
  Slot: (ctx: Ctx) => ReactElement;
  /** A feature wraps its contribution in this, to be typed against the region's context. */
  fill: (contribution: Contribution<Ctx>) => Contribution<Ctx> & { slot: string };
};

export function defineSlot<Ctx extends object = Record<string, never>>(id: string): SlotDef<Ctx> {
  return {
    id,
    // A Fragment, never a wrapper element: a slot must be usable inside <thead>/<tr> (columns and
    // row actions are slots too), where a stray <div> would be invalid markup.
    Slot: (ctx: Ctx) =>
      createElement(
        Fragment,
        null,
        forSlot(id).map((c) =>
          createElement(c.Component as ComponentType<Ctx>, { key: c.from, ...ctx }),
        ),
      ),
    fill: (contribution) => ({ slot: id, ...contribution }),
  };
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { live, personDueCents, useClaims } from '../claims/useClaims';
import { GRADES, gradeOn, heldOn, usePeople } from '../people/usePeople';
import { periodDue, usePeriods } from '../periods/usePeriods';
import { rateOn, totalDue, useRates } from '../rates/useRates';
import { useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';

const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

/**
 * The sheet in figures, each worked out as the list works it out. Per grade: how many people not
 * retired are on it on the sheet's today, and their due-totals added up (n/a ones skipped). Per
 * period: its due-total. Per status: how many of the sheet's claims have it.
 */
function SummaryPanel({ sheet }: { user: string; sheet: string }) {
  const { data: all = [] } = useClaims(sheet);
  const { data: everyone = [] } = usePeople(sheet);
  const { data: periods = [] } = usePeriods(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const people = everyone.filter((p) => !p.retired);
  const dueOf = (p: (typeof people)[number]) =>
    personDueCents(
      live(all.filter((c) => c.personId === p.id), (_, date) => heldOn(p, date)),
      floor,
      rateOn(rates, gradeOn(p, today), today),
      (d) => rateOn(rates, gradeOn(p, d), d),
      late,
    );

  return (
    <section data-testid="summary-panel">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const on = people.filter((p) => gradeOn(p, today) === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{on.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{totalDue(on.map(dueOf))}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodDue(p, all, everyone, rates, floor, late)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{all.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPanels.fill({ order: 25, Component: SummaryPanel });
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { gradeOn, heldOnBy, usePeople } from '../people/usePeople';
import { rateOn, totalDue, useRates } from '../rates/useRates';
import { useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { claimed, live, overdueFigures, personDueCents, useClaims } from './useClaims';

/**
 * The sheet's claimed-total, everyone's counted (OPEN or SETTLED) claims added up
 * (not OPEN ones dated within their person's hold, unless stated), and its due-total, everyone's due-total
 * added up (a person whose due-total is n/a is skipped), and how many of the claims that count are
 * overdue, with their dues added up.
 */
function ClaimedTotal({ sheet }: { user: string; sheet: string }) {
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const claims = live(all, heldOnBy(people));
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const dues = people.map((p) =>
    personDueCents(claims.filter((c) => c.personId === p.id), floor, rateOn(rates, gradeOn(p, today), today), (d) => rateOn(rates, gradeOn(p, d), d), late),
  );
  const over = people.map((p) =>
    overdueFigures(claims.filter((c) => c.personId === p.id), late, floor, (d) => rateOn(rates, gradeOn(p, d), d)),
  );
  return (
    <>
      <p>
        Claimed in total: <strong data-testid="rollup-claimed-total">{claimed(claims)}</strong>
      </p>
      <p>
        Due in total: <strong data-testid="rollup-due-total">{totalDue(dues)}</strong>
      </p>
      <p>
        Overdue: <strong data-testid="rollup-overdue-count">{over.reduce((n, o) => n + o.count, 0)}</strong>, due{' '}
        <strong data-testid="rollup-overdue-total">{totalDue(over.map((o) => o.cents))}</strong>
      </p>
    </>
  );
}

export const contribution = SheetPanels.fill({ order: 20, Component: ClaimedTotal });

